import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  TextField,
  Button,
  Card,
  CardContent,
  Typography,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Select,
  MenuItem,
  InputLabel,
  FormControl,
  Alert
} from '@mui/material';
import { styled } from '@mui/system';
import apiCall from '../api';
import { useUserData } from '../UserContext';

// Update the StyledCard component definition
const StyledCard = styled(Card)(({ theme }) => ({
  border: `1px solid ${theme.palette.divider}`,
  borderRadius: theme.shape.borderRadius,
  margin: '16px',
  display: 'inline-block',
  verticalAlign: 'top',
  backgroundColor: theme.palette.background.paper,
  color: theme.palette.text.primary,
  cursor: 'pointer',
  transition: 'border-color .15s ease',
  '&:hover': {
    borderColor: theme.palette.primary.main,
  },
  // Responsive width
  [theme.breakpoints.down('sm')]: {
    width: 'calc(100% - 32px)', // One card per row on mobile
  },
  [theme.breakpoints.up('sm')]: {
    width: 'calc(50% - 32px)', // Two cards per row on tablet
  },
  [theme.breakpoints.up('md')]: {
    width: 'calc(33.33% - 32px)', // Three cards per row on medium screens
  },
  [theme.breakpoints.up('lg')]: {
    width: 'calc(25% - 32px)', // Four cards per row on large screens
  },
}));

const StyledButton = styled(Button)(({ theme }) => ({
  backgroundColor: theme.palette.primary.main,
  color: theme.palette.primary.contrastText,
  '&:hover': {
    backgroundColor: theme.palette.primary.dark,
  },
}));

const CreditTransferTab = () => {
  const { userData } = useUserData();
  const [loyaltyData, setLoyaltyData] = useState([]);
  const [searchQuery, setSearchQuery] = useState('');
  const [profileOpen, setProfileOpen] = useState(false);
  const [changeValueOpen, setChangeValueOpen] = useState(false);
  const [subscriptionOpen, setSubscriptionOpen] = useState(false);
  const [currentPerson, setCurrentPerson] = useState(null);
  const [valueChange, setValueChange] = useState('');
  const [changeReason, setChangeReason] = useState('');
  const [newSubscriptionTier, setNewSubscriptionTier] = useState('0');
  const [monthsToAdd, setMonthsToAdd] = useState('');
  const [subscriptionCost, setSubscriptionCost] = useState('');
  const [changeRafflePointsOpen, setChangeRafflePointsOpen] = useState(false);
  const [rafflePointsChange, setRafflePointsChange] = useState('');
  const [rafflePointsChangeReason, setRafflePointsChangeReason] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [isValueChangeLoading, setIsValueChangeLoading] = useState(false);
  const [isRafflePointsLoading, setIsRafflePointsLoading] = useState(false);
  
  const fetchLoyaltyData = useCallback(async () => {
    setIsLoading(true);
    try {
      const scriptId = 'loyalty_script';
      const action = 'getLoyaltyData';
      const response = await apiCall(scriptId, action, { 
        username: userData.username, 
        googleToken: userData.googleToken
      });
      
      // Sort the response data alphabetically by Name
      const sortedData = response.sort((a, b) => {
        return a.Name.localeCompare(b.Name);
      });
      
      setLoyaltyData(sortedData);
    } catch (error) {
      console.error('Error fetching loyalty data:', error);
      alert('Error loading data. Please try again.');
    } finally {
      setIsLoading(false);
    }
  }, [userData.username, userData.googleToken]);
  
  useEffect(() => {
    fetchLoyaltyData();
  }, [fetchLoyaltyData]);


  const handleOpenProfile = (person) => {
    setCurrentPerson(person);
    setProfileOpen(true);
  };

  const handleCloseProfile = () => {
    if (isLoading) return;
    setProfileOpen(false);
    setCurrentPerson(null);
};

const handleCloseChangeValue = () => {
    if (isValueChangeLoading) return;  // Check valueChange-specific loading
    setChangeValueOpen(false);
    setValueChange('');
    setChangeReason('');
};

const handleCloseChangeRafflePoints = () => {
    if (isRafflePointsLoading) return;  // Check rafflePoints-specific loading
    setChangeRafflePointsOpen(false);
    setRafflePointsChange('');
    setRafflePointsChangeReason('');
};

const handleCloseSubscription = () => {
    if (isLoading) return;
    setSubscriptionOpen(false);
    setNewSubscriptionTier('0');
    setMonthsToAdd('');
    setSubscriptionCost('');
};

  const handleOpenChangeValue = () => {
    setChangeValueOpen(true);
  };


  const handleOpenSubscription = () => {
    setSubscriptionOpen(true);
  };


  const handleOpenChangeRafflePoints = () => {
    setChangeRafflePointsOpen(true);
  };

  

  // The backend answers refusals as a normal response with `error` set, so
  // check for it. Returns true when the change was saved.
  const isRejected = (response) => !response || response.success === false || !!response.error;

  const handleEditField = async (field, value) => {
    try {
      const scriptId = 'loyalty_script';
      const action = 'updateLoyaltyData';
      const response = await apiCall(scriptId, action, {id: currentPerson.Username, field, value ,googleToken: userData.googleToken , username: userData.username });
      if (isRejected(response)) {
        alert((response && response.error) || 'Could not save this change.');
        fetchLoyaltyData();
        return false;
      }
      fetchLoyaltyData();
      return true;
    } catch (error) {
      console.error('Error updating field:', error);
      return false;
    }
  };

  const handleSubmitChange = async () => {
    if (!valueChange || !changeReason) {
      alert('Please fill out both fields before submitting.');
      return;
    }

    const workerRole = userData.role;
    const overLimit = Math.abs(Number(valueChange)) >= 50;
    const isPrivileged = workerRole === "Admin" || workerRole === "Store Manager";

    if (overLimit && !isPrivileged) {
      setIsValueChangeLoading(true);
      try {
        const scriptId = 'loyalty_script';
        const action = 'sendEmailForStoreCreditChange';
        const requestResponse = await apiCall(scriptId, action, {
          username: userData.username,
          googleToken: userData.googleToken,
          change: valueChange,
          reason: changeReason,
          customerUsername: currentPerson.Username,
        });
        if (isRejected(requestResponse)) {
          alert((requestResponse && requestResponse.error) || 'Error sending notification. Please try again.');
          return;
        }
        alert("You are not authorized to change store credit exceeding 50 euros. The Store manager and admin have been notified and will manually change it. Thank you.");
        handleCloseChangeValue();
      } catch (error) {
        console.error('Error sending authorization request:', error);
        alert('Error sending notification. Please try again.');
      } finally {
        setIsValueChangeLoading(false);
      }
      return;
    }

    setIsValueChangeLoading(true);
    try {
      const scriptId = 'loyalty_script';
      const action = 'changeValue';
      const response = await apiCall(scriptId, action, {
        id: currentPerson.Username,
        valueChange,
        changeReason,
        googleToken: userData.googleToken,
        username: userData.username
      });
      if (isRejected(response)) {
        alert((response && response.error) || 'Error making change. Please try again.');
        return;
      }
      handleCloseChangeValue();
      await fetchLoyaltyData();
      alert(response.pendingApproval
        ? 'This is a staff account, so the change has been sent for approval. It will be applied once an admin or store manager approves it.'
        : 'Change has been made');
    } catch (error) {
      console.error('Error submitting change:', error);
      alert('Error making change. Please try again.');
    } finally {
      setIsValueChangeLoading(false);
    }
  };
  
  const handleSubmitRafflePointsChange = async () => {
    if (!rafflePointsChange || !rafflePointsChangeReason) {
      alert('Please fill out both fields before submitting.');
      return;
    }
  
    setIsRafflePointsLoading(true);
    try {
      const scriptId = 'loyalty_script';
      const action = 'changeRafflePoints';
      const response = await apiCall(scriptId, action, {
        id: currentPerson.Username,
        valueChange: rafflePointsChange,
        changeReason: rafflePointsChangeReason,
        googleToken: userData.googleToken,
        username: userData.username
      });
      if (isRejected(response)) {
        alert((response && response.error) || 'Error making change. Please try again.');
        return;
      }
      handleCloseChangeRafflePoints(); // Move this before fetchLoyaltyData
      await fetchLoyaltyData();
      alert('Change has been made');
    } catch (error) {
      console.error('Error submitting raffle points change:', error);
      alert('Error making change. Please try again.');
    } finally {
      setIsRafflePointsLoading(false);
    }
  };

  const calculateSubscriptionCost = () => {
    const costPerMonth = getTierCost(newSubscriptionTier);
    const totalCost = costPerMonth * parseInt(monthsToAdd);
    setSubscriptionCost(`Cost: ${totalCost}`);
  };

  const handleSubmitSubscriptionChange = async () => {
    if (!currentPerson.Email) {
      alert('Email is required to proceed.');
      return;
    }

    const currentSubscriptionTier = currentPerson.Subscription;
    const currentExpiryDate = new Date(currentPerson['Expiry Date']);
    const today = new Date();

    if (currentSubscriptionTier !== '0' && today <= currentExpiryDate) {
      alert(`Cannot change the subscription until the current subscription expires on ${currentPerson['Expiry Date']}.`);
      return;
    }

    today.setMonth(today.getMonth() + parseInt(monthsToAdd));
    const expiryDate = today.toISOString().split('T')[0];

    const tierCost = getTierCost(newSubscriptionTier) * parseInt(monthsToAdd);

    if (window.confirm(`The cost for the new subscription is ${tierCost} euros. Do you want to proceed?`)) {
      try {
        const scriptId = 'loyalty_script';
        const actionUpdateEmail = 'updateLoyaltyData';
        const actionUpdateSubscription = 'updateSubscription';
        const actionSendInvoice = 'sendInvoice';

        const emailResponse = await apiCall(scriptId, actionUpdateEmail, {id: currentPerson.Username, field: 'Email', value: currentPerson.Email, googleToken: userData.googleToken , username: userData.username  });
        if (isRejected(emailResponse)) {
          alert((emailResponse && emailResponse.error) || 'Could not update the subscription.');
          return;
        }
        const subscriptionResponse = await apiCall(scriptId, actionUpdateSubscription, {id: currentPerson.Username, newTier: newSubscriptionTier, expiryDate, googleToken: userData.googleToken , username: userData.username  });
        if (isRejected(subscriptionResponse)) {
          alert((subscriptionResponse && subscriptionResponse.error) || 'Could not update the subscription.');
          return;
        }
        await apiCall(scriptId, actionSendInvoice, {email: currentPerson.Email, newTier: newSubscriptionTier, tierCost, googleToken: userData.googleToken , username: userData.username  });

        handleCloseSubscription();
        fetchLoyaltyData();
      } catch (error) {
        console.error('Error updating subscription:', error);
      }
    }
  };

  const getTierCost = (tier) => {
    const tierCosts = { '0': 0, '1': 10, '2': 20, '3': 30, '4': 50 };
    return tierCosts[tier] || 0;
  };

  // What this worker may do to the account in the popup. This only greys things
  // out for clarity; the backend (accessControl.js) enforces the same rules.
  const normalizeEmail = (value) => String(value == null ? '' : value).trim().toLowerCase();
  const isPrivilegedUser = userData.role === 'Admin' || userData.role === 'Store Manager';
  const myEmail = normalizeEmail(userData.email);
  const isOwnAccount = !!currentPerson && myEmail !== '' && normalizeEmail(currentPerson.Email) === myEmail;
  const isWorkerAccount = !!currentPerson && String(currentPerson.Worker == null ? '' : currentPerson.Worker).trim().toUpperCase() === 'TRUE';
  // Admins / Store Managers keep full access to their own account.
  const lockAccount = isOwnAccount && !isPrivilegedUser;
  const lockEmail = lockAccount || (isWorkerAccount && !isPrivilegedUser);
  const needsApproval = isWorkerAccount && !(isOwnAccount && isPrivilegedUser);
  const raffleBlocked = lockAccount || needsApproval;

  const filteredData = loyaltyData.filter(person => 
    person.Name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <Box sx={{ backgroundColor: 'background.default', color: 'text.primary', padding: '20px', position: 'relative' }}>
      {/* Loading Overlay */}
      {isLoading && (
        <Box
          sx={{
            position: 'fixed',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(0, 0, 0, 0.7)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 9999,
          }}
        >
          <Box
            sx={{
              backgroundColor: 'background.paper',
              padding: '20px',
              borderRadius: '8px',
              textAlign: 'center'
            }}
          >
            <Typography variant="h6" sx={{ color: 'text.primary', marginBottom: '10px' }}>
              Loading Data...
            </Typography>
            <Box
              sx={{
                display: 'inline-block',
                width: '40px',
                height: '40px',
                border: '4px solid',
                borderColor: 'primary.main',
                borderTop: '4px solid transparent',
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                '@keyframes spin': {
                  '0%': {
                    transform: 'rotate(0deg)',
                  },
                  '100%': {
                    transform: 'rotate(360deg)',
                  },
                },
              }}
            />
          </Box>
        </Box>
      )}
  
      <TextField
        fullWidth
        variant="outlined"
        placeholder="Search for names..."
        value={searchQuery}
        onChange={(e) => setSearchQuery(e.target.value)}
        disabled={isLoading}
        sx={{
          marginBottom: '16px',
          '& .MuiOutlinedInput-root': {
            '& fieldset': { borderColor: 'primary.main' },
            '&:hover fieldset': { borderColor: 'primary.main' },
            '&.Mui-focused fieldset': { borderColor: 'primary.main' },
          },
          '& .MuiInputBase-input': { color: 'text.primary' },
        }}
      />
      <StyledButton 
        onClick={fetchLoyaltyData}
        disabled={isLoading}
      >
        {isLoading ? 'Loading...' : 'Refresh'}
      </StyledButton>
      
      <Box sx={{ 
        display: 'flex', 
        flexWrap: 'wrap',
        pointerEvents: isLoading ? 'none' : 'auto',
        opacity: isLoading ? 0.7 : 1
      }}>
        {filteredData.map((person, index) => (
          <StyledCard 
            key={index} 
            onClick={() => handleOpenProfile(person)}
            sx={{ cursor: isLoading ? 'default' : 'pointer' }}
          >
            <CardContent>
              <Typography variant="h6">{person.Name}</Typography>
              <Typography 
                variant="body2" 
                sx={{
                  color: 'text.secondary',  // Slightly lighter color for the subheading
                  marginTop: '4px'
                }}
              >
                {person.Username}
              </Typography>
            </CardContent>
          </StyledCard>
        ))}
      </Box>
  
      <Dialog
        open={profileOpen}
        onClose={handleCloseProfile}
        disableEscapeKeyDown={isLoading}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>{currentPerson?.Name}</DialogTitle>
        <DialogContent>
          <Box sx={{ display: 'flex', flexDirection: 'column', gap: 3 }}>
            {lockAccount ? (
              <Alert severity="info">
                This is your own account, so it can't be changed from here.
              </Alert>
            ) : needsApproval ? (
              <Alert severity="warning">
                This is a staff account. Credit changes need approval and raffle points can't be changed
                {isPrivilegedUser ? '.' : ', and the email can\'t be edited.'}
              </Alert>
            ) : null}

            {/* Store Credit Section */}
            <Box>
              <Typography variant="h6" gutterBottom>Store Credit</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Typography>{currentPerson?.Value}</Typography>
                <StyledButton 
                  onClick={handleOpenChangeValue}
                  disabled={isLoading || lockAccount}
                >
                  Change
                </StyledButton>
              </Box>
            </Box>
  
            {/* Raffle Points Section */}
            <Box>
              <Typography variant="h6" gutterBottom>Raffle Points</Typography>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Typography>{currentPerson?.RafflePoints}</Typography>
                <StyledButton 
                  onClick={handleOpenChangeRafflePoints}
                  disabled={isLoading || raffleBlocked}
                >
                  Change
                </StyledButton>
              </Box>
            </Box>
  
            {/* Details Section */}
            <Box>
              <Typography variant="h6" gutterBottom>Details</Typography>
              <TextField
                fullWidth
                defaultValue={currentPerson?.Details}
                onBlur={async (e) => {
                  const input = e.target;
                  const saved = await handleEditField('Details', input.value);
                  if (!saved) input.value = currentPerson?.Details ?? '';
                }}
                disabled={isLoading || lockAccount}
              />
            </Box>
  
            {/* Subscription Section */}
            <Box>
              <Typography variant="h6" gutterBottom>Subscription Details</Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1 }}>
                <Typography>Current Tier: {currentPerson?.Subscription}</Typography>
                <Typography>Expiry Date: {currentPerson?.['Expiry Date']}</Typography>
                <StyledButton 
                  onClick={handleOpenSubscription}
                  disabled={isLoading || lockAccount}
                >
                  Change Subscription
                </StyledButton>
              </Box>
            </Box>
  
            {/* Member Info Section */}
            <Box>
              <Typography variant="h6" gutterBottom>Member Information</Typography>
              <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
                <Typography>Member ID: {currentPerson?.Username}</Typography>
                <TextField
                  label="Email"
                  fullWidth
                  defaultValue={currentPerson?.Email}
                  onBlur={async (e) => {
                    const input = e.target;
                    const saved = await handleEditField('Email', input.value);
                    if (!saved) input.value = currentPerson?.Email ?? '';
                  }}
                  disabled={isLoading || lockEmail}
                />
              </Box>
            </Box>
          </Box>
        </DialogContent>
        <DialogActions>
          <StyledButton 
            onClick={handleCloseProfile}
            disabled={isLoading}
          >
            Close
          </StyledButton>
        </DialogActions>
      </Dialog>
  
      <Dialog
        open={changeValueOpen}
        onClose={handleCloseChangeValue}
        disableEscapeKeyDown={isValueChangeLoading}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Change Value</DialogTitle>
        <DialogContent>
          {needsApproval && (
            <Alert severity="warning" sx={{ mb: 1 }}>
              This is a staff account, so this change will be sent for approval instead of being applied straight away.
            </Alert>
          )}
          <TextField
            label="Value Change"
            type="number"
            value={valueChange}
            onChange={(e) => setValueChange(e.target.value)}
            fullWidth
            margin="normal"
            disabled={isValueChangeLoading}
          />
          <TextField
            label="Reason"
            multiline
            rows={8}  // Increased from 4 to 8 rows
            value={changeReason}
            onChange={(e) => setChangeReason(e.target.value)}
            fullWidth
            margin="normal"
            disabled={isValueChangeLoading}
            sx={{
              '& .MuiOutlinedInput-root': {
                minHeight: '200px',  // Add minimum height
              },
              '& .MuiInputBase-input': {
                overflowY: 'auto',   // Add scrolling for overflow
                lineHeight: '1.5',   // Improve line spacing for readability
              }
            }}
          />
        </DialogContent>
        <DialogActions>
          <StyledButton 
            onClick={handleSubmitChange} 
            disabled={isValueChangeLoading}
          >
            {isValueChangeLoading ? 'Loading...' : 'Submit'}
          </StyledButton>
          <StyledButton 
            onClick={handleCloseChangeValue}
            disabled={isValueChangeLoading}
          >
            Cancel
          </StyledButton>
        </DialogActions>
      </Dialog>
  
      <Dialog
        open={subscriptionOpen}
        onClose={handleCloseSubscription}
        disableEscapeKeyDown={isLoading}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Change Subscription</DialogTitle>
        <DialogContent>
          <FormControl fullWidth margin="normal">
            <InputLabel>New Subscription Tier</InputLabel>
            <Select
              value={newSubscriptionTier}
              onChange={(e) => setNewSubscriptionTier(e.target.value)}
              disabled={isLoading}
            >
              <MenuItem value="0">Tier 0</MenuItem>
              <MenuItem value="1">Tier 1</MenuItem>
              <MenuItem value="2">Tier 2</MenuItem>
              <MenuItem value="3">Tier 3</MenuItem>
              <MenuItem value="4">Tier 4</MenuItem>
            </Select>
          </FormControl>
          <TextField
            label="Months to Add"
            type="number"
            value={monthsToAdd}
            onChange={(e) => setMonthsToAdd(e.target.value)}
            fullWidth
            margin="normal"
            disabled={isLoading}
          />
          <TextField
            label="Email"
            value={currentPerson?.Email || ''}
            disabled
            fullWidth
            margin="normal"
          />
          <StyledButton 
            onClick={calculateSubscriptionCost}
            disabled={isLoading}
          >
            Calculate Cost
          </StyledButton>
          <Typography>{subscriptionCost}</Typography>
        </DialogContent>
        <DialogActions>
          <StyledButton 
            onClick={handleSubmitSubscriptionChange}
            disabled={isLoading}
          >
            Submit
          </StyledButton>
          <StyledButton 
            onClick={handleCloseSubscription}
            disabled={isLoading}
          >
            Cancel
          </StyledButton>
        </DialogActions>
      </Dialog>
  
      <Dialog
        open={changeRafflePointsOpen}
        onClose={handleCloseChangeRafflePoints}
        disableEscapeKeyDown={isRafflePointsLoading}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Change Raffle Points</DialogTitle>
        <DialogContent>
          <TextField
            label="Points Change"
            type="number"
            value={rafflePointsChange}
            onChange={(e) => setRafflePointsChange(e.target.value)}
            fullWidth
            margin="normal"
            disabled={isRafflePointsLoading}
          />
          <TextField
            label="Reason"
            multiline
            rows={4}
            value={rafflePointsChangeReason}
            onChange={(e) => setRafflePointsChangeReason(e.target.value)}
            fullWidth
            margin="normal"
            disabled={isRafflePointsLoading}
          />
        </DialogContent>
        <DialogActions>
          <StyledButton 
            onClick={handleSubmitRafflePointsChange}
            disabled={isRafflePointsLoading}
          >
            {isRafflePointsLoading ? 'Loading...' : 'Submit'}
          </StyledButton>
          <StyledButton 
            onClick={handleCloseChangeRafflePoints}
            disabled={isRafflePointsLoading}
          >
            Cancel
          </StyledButton>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default CreditTransferTab;