import React, { useState, useEffect, useCallback } from "react";
import { Box, Tabs, Tab, Badge } from "@mui/material";
import { styled } from "@mui/system";
import apiCall from "../api";
import { useUserData } from "../UserContext";
import CreditTransferTab from "./CreditTransferTab";
import ApprovalsTab from "./ApprovalsTab";
import RecentChangesTab from "./RecentChangesTab";
// Styled components for consistent theming
const StyledTabs = styled(Tabs)(({ theme }) => ({
  backgroundColor: theme.palette.background.paper,
  "& .MuiTabs-indicator": {
    backgroundColor: theme.palette.primary.main,
  },
}));

const StyledTab = styled(Tab)(({ theme }) => ({
  color: theme.palette.text.secondary,
  "&.Mui-selected": {
    color: theme.palette.primary.main,
  },
  "&:hover": {
    color: theme.palette.primary.main,
  },
}));

const TabPanel = ({ children, value, index, ...other }) => {
  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`loyalty-tabpanel-${index}`}
      aria-labelledby={`loyalty-tab-${index}`}
      {...other}
    >
      {value === index && <Box>{children}</Box>}
    </div>
  );
};

const LoyaltyDashboard = ({ onMaxWidthChange }) => {
  const { userData } = useUserData();
  const [tabValue, setTabValue] = useState(0);
  const [pendingCount, setPendingCount] = useState(0);
  const [filterOptions, setFilterOptions] = useState({ customerNames: [], workerNames: [] });

  const refreshPendingCount = useCallback(async () => {
    try {
      const response = await apiCall("loyalty_script", "getPendingApprovalsCount", {
        username: userData.username,
        googleToken: userData.googleToken,
      });
      setPendingCount(response?.count || 0);
    } catch (err) {
      console.error("Failed to fetch pending approvals count:", err);
    }
  }, [userData]);

  useEffect(() => {
    refreshPendingCount();
  }, [refreshPendingCount]);

  // Fetched once here (not per-tab, not per-paginated-request) since the
  // roster sheets it reads barely change compared to transaction data.
  useEffect(() => {
    const fetchFilterOptions = async () => {
      try {
        const response = await apiCall("loyalty_script", "getFilterOptions", {
          username: userData.username,
          googleToken: userData.googleToken,
        });
        setFilterOptions(response || { customerNames: [], workerNames: [] });
      } catch (err) {
        console.error("Failed to fetch filter options:", err);
      }
    };
    fetchFilterOptions();
  }, [userData]);

  const handleTabChange = (event, newValue) => {
    setTabValue(newValue);

    if (onMaxWidthChange) {
      if (newValue === 1 || newValue === 2) {
        onMaxWidthChange("lg");
      } else {
        onMaxWidthChange("md");
      }
    }
  };

  return (
    <Box sx={{ backgroundColor: "background.default", color: "text.primary", minHeight: "100%" }}>
      <Box sx={{ borderBottom: 1, borderColor: "divider" }}>
        <StyledTabs
          value={tabValue}
          onChange={handleTabChange}
          aria-label="loyalty dashboard tabs"
          variant="fullWidth"
        >
          <StyledTab label="Transfer Credit" />
          <StyledTab
            label={
              <Badge
                badgeContent={pendingCount}
                color="error"
                sx={{ "& .MuiBadge-badge": { right: -14, top: -2 } }}
              >
                Approvals
              </Badge>
            }
          />
          <StyledTab label="Recent Changes" />
        </StyledTabs>
      </Box>

      <TabPanel value={tabValue} index={0}>
        <CreditTransferTab />
      </TabPanel>

      <TabPanel value={tabValue} index={1}>
        <ApprovalsTab onApprovalsChanged={refreshPendingCount} filterOptions={filterOptions} />
      </TabPanel>

      <TabPanel value={tabValue} index={2}>
        <RecentChangesTab filterOptions={filterOptions} />
      </TabPanel>
    </Box>
  );
};

export default LoyaltyDashboard;
