import React, { useState, useEffect, useCallback, useMemo } from "react";
import {
  Box,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Chip,
  Stack,
  Autocomplete,
  TextField,
  MenuItem,
  IconButton,
  Menu,
  Checkbox,
  FormControlLabel,
} from "@mui/material";
import ViewColumnIcon from "@mui/icons-material/ViewColumn";
import { styled } from "@mui/system";
import { DatePicker } from "@mui/x-date-pickers/DatePicker";
import { LocalizationProvider } from "@mui/x-date-pickers/LocalizationProvider";
import { AdapterDayjs } from "@mui/x-date-pickers/AdapterDayjs";
import dayjs from "dayjs";
import apiCall from "../api";
import { useUserData } from "../UserContext";

const StyledTableContainer = styled(TableContainer)(({ theme }) => ({
  backgroundColor: theme.palette.background.paper,
  "& .MuiTable-root": {
    color: theme.palette.text.primary,
  },
  "& .MuiTableCell-root": {
    color: theme.palette.text.primary,
    borderBottom: `1px solid ${theme.palette.divider}`,
    verticalAlign: "top",
  },
  "& .MuiTableHead-root .MuiTableCell-root": {
    backgroundColor: theme.palette.action.hover,
    fontWeight: "bold",
    fontSize: "0.9rem",
    verticalAlign: "middle",
  },
}));

const StyledButton = styled(Button)(({ theme }) => ({
  backgroundColor: theme.palette.primary.main,
  color: theme.palette.primary.contrastText,
  margin: "0 4px",
  "&:hover": {
    backgroundColor: theme.palette.primary.dark,
  },
}));

const ApproveButton = styled(Button)(({ theme }) => ({
  backgroundColor: theme.palette.success.main,
  color: theme.palette.success.contrastText,
  margin: "0 4px",
  "&:hover": {
    backgroundColor: theme.palette.success.dark,
  },
}));

const DenyButton = styled(Button)(({ theme }) => ({
  backgroundColor: theme.palette.error.main,
  color: theme.palette.error.contrastText,
  margin: "0 4px",
  "&:hover": {
    backgroundColor: theme.palette.error.dark,
  },
}));

const STATUS_OPTIONS = ["Pending approval", "Approved", "Denied"];

// Config-driven so the "show/hide columns" menu and the table body stay in
// sync without repeating the column list in two places.
const COLUMN_DEFS = [
  { key: "ID", label: "ID", field: "ID", sortable: true },
  { key: "WorkerName", label: "Worker Name", field: "WorkerName", sortable: true },
  { key: "RequestDate", label: "Request Date", field: "RequestDate", sortable: true },
  { key: "CustomerName", label: "Customer Name", field: "Customer Name", sortable: true },
  { key: "Username", label: "Customer Username", sortable: false },
  { key: "ChangeAmount", label: "Change Amount", field: "Change Amount", sortable: true },
  { key: "Existing", label: "Existing", sortable: false },
  { key: "AfterChange", label: "After Change", sortable: false },
  { key: "Status", label: "Status", field: "Status", sortable: true },
  { key: "ApprovedBy", label: "Approved By", sortable: false },
  { key: "Reason", label: "Reason", sortable: false },
];

const COLUMN_VISIBILITY_STORAGE_KEY = "loyaltyApprovalsVisibleColumns";

const loadVisibleColumns = () => {
  try {
    const stored = JSON.parse(localStorage.getItem(COLUMN_VISIBILITY_STORAGE_KEY));
    if (stored && typeof stored === "object") {
      return { ...Object.fromEntries(COLUMN_DEFS.map((c) => [c.key, true])), ...stored };
    }
  } catch (error) {
    // Ignore malformed/blocked storage and fall back to defaults.
  }
  return Object.fromEntries(COLUMN_DEFS.map((c) => [c.key, true]));
};

const ApprovalsTab = ({ onApprovalsChanged, filterOptions }) => {
  const { userData } = useUserData();
  const [approvals, setApprovals] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [confirmDialogOpen, setConfirmDialogOpen] = useState(false);
  const [selectedApproval, setSelectedApproval] = useState(null);
  const [actionType, setActionType] = useState(""); // 'approve' or 'deny'

  const [customerName, setCustomerName] = useState("");
  const [workerName, setWorkerName] = useState("");
  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [status, setStatus] = useState("");
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [totalAmount, setTotalAmount] = useState(0);
  const [sortBy, setSortBy] = useState("RequestDate");
  const [sortDir, setSortDir] = useState("desc");

  const [columnMenuAnchor, setColumnMenuAnchor] = useState(null);
  const [visibleColumns, setVisibleColumns] = useState(loadVisibleColumns);
  const [reasonDialogText, setReasonDialogText] = useState(null);

  const options = filterOptions || { customerNames: [], workerNames: [] };

  useEffect(() => {
    try {
      localStorage.setItem(COLUMN_VISIBILITY_STORAGE_KEY, JSON.stringify(visibleColumns));
    } catch (error) {
      // Ignore storage failures (private browsing, quota, etc.)
    }
  }, [visibleColumns]);

  const toggleColumn = (key) => {
    setVisibleColumns((prev) => ({ ...prev, [key]: !prev[key] }));
  };

  const columns = useMemo(
    () => COLUMN_DEFS.filter((c) => visibleColumns[c.key] !== false),
    [visibleColumns]
  );

  const fetchApprovals = useCallback(async () => {
    setIsLoading(true);
    try {
      const scriptId = "loyalty_script";
      const action = "getAllApprovals";
      const response = await apiCall(scriptId, action, {
        username: userData.username,
        googleToken: userData.googleToken,
        customerName,
        workerName,
        startDate,
        endDate,
        status,
        page,
        pageSize: 50,
        sortBy,
        sortDir,
      });

      setApprovals(response.items || []);
      setTotalPages(response.totalPages || 1);
      setTotalAmount(response.totalAmount || 0);
      if (onApprovalsChanged) onApprovalsChanged();
    } catch (error) {
      console.error("Error fetching approvals:", error);
      alert("Error loading approvals. Please try again.");
    } finally {
      setIsLoading(false);
    }
  }, [
    userData.username,
    userData.googleToken,
    customerName,
    workerName,
    startDate,
    endDate,
    status,
    page,
    sortBy,
    sortDir,
    onApprovalsChanged,
  ]);

  useEffect(() => {
    fetchApprovals();
  }, [fetchApprovals]);

  // Reset to page 1 whenever a filter changes, debounced so typing doesn't
  // fire a request on every keystroke.
  useEffect(() => {
    const timeout = setTimeout(() => setPage(1), 400);
    return () => clearTimeout(timeout);
  }, [customerName, workerName, startDate, endDate, status]);

  const handleSort = (field) => {
    if (sortBy === field) {
      setSortDir((prev) => (prev === "asc" ? "desc" : "asc"));
    } else {
      setSortBy(field);
      setSortDir("desc");
    }
  };

  const clearFilters = () => {
    setCustomerName("");
    setWorkerName("");
    setStartDate("");
    setEndDate("");
    setStatus("");
    setPage(1);
  };

  const handleApprovalAction = (approval, isApproved) => {
    setSelectedApproval(approval);
    setActionType(isApproved ? "approve" : "deny");
    setConfirmDialogOpen(true);
  };

  const confirmAction = async () => {
    if (!selectedApproval) return;

    setIsLoading(true);
    try {
      const scriptId = "loyalty_script";
      const action = "handleApprovalAction";

      const response = await apiCall(scriptId, action, {
        id: selectedApproval.ID,
        workerName: selectedApproval.WorkerName,
        customerName: selectedApproval["Customer Name"],
        customerUsername: selectedApproval.Username,
        existingAmount: selectedApproval.Existing,
        changeAmount: selectedApproval["Change Amount"],
        amountAfter: selectedApproval["After Change"],
        isApproved: actionType === "approve",
        username: userData.username,
        reason: selectedApproval.Reason,
        googleToken: userData.googleToken,
      });

      // Handle backend response
      if (response && response.success) {
        alert(
          response.message ||
            `Request has been ${
              actionType === "approve" ? "approved" : "denied"
            } successfully.`
        );
        setConfirmDialogOpen(false);
        setSelectedApproval(null);
        setActionType("");
        await fetchApprovals();
      } else {
        // Handle specific error messages from backend
        const errorMessage =
          response && response.error
            ? response.error
            : `Error processing request. Please try again.`;
        alert(errorMessage);
      }
    } catch (error) {
      console.error("Error processing approval:", error);
      alert(
        "Error occurred. Please try again later."
      );
    } finally {
      setIsLoading(false);
    }
  };

  const handleCloseDialog = () => {
    if (isLoading) return;
    setConfirmDialogOpen(false);
    setSelectedApproval(null);
    setActionType("");
  };

  const getStatusChip = (statusValue) => {
    let color = "default";
    if (statusValue === "Approved") color = "success";
    else if (statusValue === "Denied") color = "error";
    else if (statusValue === "Pending approval") color = "warning";

    return <Chip label={statusValue} color={color} size="small" />;
  };

  const formatTimestamp = (timestamp) => {
    if (!timestamp) return "-";

    try {
      const date = new Date(timestamp);
      if (isNaN(date.getTime())) return String(timestamp);
      const day = date.getDate().toString().padStart(2, '0');
      const month = (date.getMonth() + 1).toString().padStart(2, '0');
      const year = date.getFullYear();
      const hours = date.getHours().toString().padStart(2, '0');
      const minutes = date.getMinutes().toString().padStart(2, '0');

      return `${day}/${month}/${year} ${hours}:${minutes}`;
    } catch (error) {
      return timestamp; // Return original if parsing fails
    }
  };

  const canApprove =
    userData.role === "Admin" || userData.role === "Store Manager";

  const SortableHeader = ({ label, field }) => (
    <TableCell
      onClick={() => handleSort(field)}
      sx={{ cursor: "pointer", userSelect: "none", whiteSpace: "nowrap" }}
    >
      {label}
      {sortBy === field ? (sortDir === "asc" ? " ▲" : " ▼") : ""}
    </TableCell>
  );

  const renderCellContent = (key, approval) => {
    switch (key) {
      case "ID":
        return approval.ID;
      case "WorkerName":
        return approval.WorkerName;
      case "RequestDate":
        return formatTimestamp(approval.RequestDate);
      case "CustomerName":
        return approval["Customer Name"];
      case "Username":
        return approval.Username;
      case "ChangeAmount":
        return (
          <Box
            component="span"
            sx={{
              color:
                parseFloat(approval["Change Amount"]) >= 0
                  ? "success.main"
                  : "error.main",
            }}
          >
            {approval["Change Amount"]}
          </Box>
        );
      case "Existing":
        return approval.Existing;
      case "AfterChange":
        return approval["After Change"];
      case "Status":
        return getStatusChip(approval.Status);
      case "ApprovedBy":
        return approval["Approved By"] || "-";
      case "Reason":
        return approval.Reason ? (
          <Button
            size="small"
            onClick={() => setReasonDialogText(approval.Reason)}
            sx={{ color: "text.secondary", textTransform: "none" }}
          >
            View Reason
          </Button>
        ) : (
          "-"
        );
      default:
        return null;
    }
  };

  return (
    <Box
      sx={{
        backgroundColor: "background.default",
        color: "text.primary",
        padding: "20px",
        position: "relative",
      }}
    >
      {/* Loading Overlay */}
      {isLoading && (
        <Box
          sx={{
            position: "fixed",
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: "rgba(0, 0, 0, 0.7)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 9999,
          }}
        >
          <Box
            sx={{
              backgroundColor: "background.paper",
              padding: "20px",
              borderRadius: "8px",
              textAlign: "center",
            }}
          >
            <Typography
              variant="h6"
              sx={{ color: "text.primary", marginBottom: "10px" }}
            >
              Processing...
            </Typography>
            <Box
              sx={{
                display: "inline-block",
                width: "40px",
                height: "40px",
                border: "4px solid",
                borderColor: "primary.main",
                borderTop: "4px solid transparent",
                borderRadius: "50%",
                animation: "spin 1s linear infinite",
                "@keyframes spin": {
                  "0%": {
                    transform: "rotate(0deg)",
                  },
                  "100%": {
                    transform: "rotate(360deg)",
                  },
                },
              }}
            />
          </Box>
        </Box>
      )}

      <Box
        sx={{
          marginBottom: "20px",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: 2,
        }}
      >
        <Typography variant="h4" sx={{ color: "primary.main" }}>
          Approval Requests
        </Typography>
        <Box sx={{ display: "flex", gap: 1 }}>
          <IconButton
            onClick={(e) => setColumnMenuAnchor(e.currentTarget)}
            sx={{ color: "text.secondary" }}
            title="Show/hide columns"
          >
            <ViewColumnIcon />
          </IconButton>
          <StyledButton onClick={fetchApprovals} disabled={isLoading}>
            {isLoading ? "Loading..." : "Refresh"}
          </StyledButton>
        </Box>
      </Box>

      <Menu
        anchorEl={columnMenuAnchor}
        open={Boolean(columnMenuAnchor)}
        onClose={() => setColumnMenuAnchor(null)}
      >
        {COLUMN_DEFS.map((col) => (
          <MenuItem key={col.key} dense onClick={() => toggleColumn(col.key)}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={visibleColumns[col.key] !== false}
                  onChange={() => toggleColumn(col.key)}
                  onClick={(e) => e.stopPropagation()}
                />
              }
              label={col.label}
              sx={{ width: "100%", marginRight: 0 }}
            />
          </MenuItem>
        ))}
      </Menu>

      <Box sx={{ display: "flex", gap: 2, flexWrap: "wrap", marginBottom: 2 }}>
        <Autocomplete
          freeSolo
          options={options.customerNames}
          value={customerName || null}
          onChange={(e, value) => setCustomerName(value || "")}
          sx={{ minWidth: 220 }}
          renderInput={(params) => (
            <TextField {...params} label="Customer Name" size="small" />
          )}
        />
        <Autocomplete
          freeSolo
          options={options.workerNames}
          value={workerName || null}
          onChange={(e, value) => setWorkerName(value || "")}
          sx={{ minWidth: 220 }}
          renderInput={(params) => (
            <TextField {...params} label="Worker" size="small" />
          )}
        />
        <TextField
          select
          label="Status"
          size="small"
          value={status}
          onChange={(e) => setStatus(e.target.value)}
          sx={{ minWidth: 180 }}
        >
          <MenuItem value="">All</MenuItem>
          {STATUS_OPTIONS.map((s) => (
            <MenuItem key={s} value={s}>
              {s}
            </MenuItem>
          ))}
        </TextField>
        <LocalizationProvider dateAdapter={AdapterDayjs}>
          <DatePicker
            label="From"
            value={startDate ? dayjs(startDate) : null}
            onChange={(date) =>
              setStartDate(date && date.isValid() ? date.format("YYYY-MM-DD") : "")
            }
            slotProps={{ textField: { size: "small", sx: { minWidth: 160 } } }}
          />
          <DatePicker
            label="To"
            value={endDate ? dayjs(endDate) : null}
            onChange={(date) =>
              setEndDate(date && date.isValid() ? date.format("YYYY-MM-DD") : "")
            }
            minDate={startDate ? dayjs(startDate) : undefined}
            slotProps={{ textField: { size: "small", sx: { minWidth: 160 } } }}
          />
        </LocalizationProvider>
        <Button
          onClick={clearFilters}
          sx={{ color: "text.secondary", borderColor: "divider" }}
          variant="outlined"
        >
          Clear Filters
        </Button>
      </Box>

      <Typography variant="body2" sx={{ color: "text.secondary", marginBottom: 2 }}>
        Total change amount for current filter (all matching pages, not just this one):{" "}
        <Box component="strong" sx={{ color: totalAmount >= 0 ? "success.main" : "error.main" }}>
          {totalAmount >= 0 ? "+" : ""}
          {totalAmount}
        </Box>
      </Typography>

      <StyledTableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow>
              {columns.map((col) =>
                col.sortable ? (
                  <SortableHeader key={col.key} label={col.label} field={col.field} />
                ) : (
                  <TableCell key={col.key}>{col.label}</TableCell>
                )
              )}
              {canApprove && <TableCell>Actions</TableCell>}
            </TableRow>
          </TableHead>
          <TableBody>
            {approvals.map((approval) => (
              <TableRow key={approval.ID}>
                {columns.map((col) => (
                  <TableCell key={col.key}>
                    {renderCellContent(col.key, approval)}
                  </TableCell>
                ))}
                {canApprove && (
                  <TableCell>
                    {approval.Status === "Pending approval" ? (
                      <Stack sx={{ display: "flex", gap: 2 }}>
                        <ApproveButton
                          size="small"
                          onClick={() => handleApprovalAction(approval, true)}
                          disabled={isLoading}
                        >
                          Approve
                        </ApproveButton>
                        <DenyButton
                          size="small"
                          onClick={() => handleApprovalAction(approval, false)}
                          disabled={isLoading}
                        >
                          Deny
                        </DenyButton>
                      </Stack>
                    ) : (
                      "-"
                    )}
                  </TableCell>
                )}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </StyledTableContainer>

      {approvals.length === 0 && !isLoading && (
        <Box sx={{ textAlign: "center", marginTop: "40px" }}>
          <Typography variant="body1" sx={{ color: "text.secondary" }}>
            No approval requests found.
          </Typography>
        </Box>
      )}

      <Box sx={{ display: "flex", justifyContent: "center", gap: 2, marginTop: "20px" }}>
        <StyledButton disabled={page <= 1 || isLoading} onClick={() => setPage((p) => p - 1)}>
          Previous
        </StyledButton>
        <Typography sx={{ alignSelf: "center", color: "text.secondary" }}>
          Page {page} of {totalPages}
        </Typography>
        <StyledButton disabled={page >= totalPages || isLoading} onClick={() => setPage((p) => p + 1)}>
          Next
        </StyledButton>
      </Box>

      {/* Confirmation Dialog */}
      <Dialog
        open={confirmDialogOpen}
        onClose={handleCloseDialog}
        disableEscapeKeyDown={isLoading}
      >
        <DialogTitle>
          Confirm {actionType === "approve" ? "Approval" : "Denial"}
        </DialogTitle>
        <DialogContent>
          <Typography variant="body1" sx={{ marginBottom: "16px" }}>
            Are you sure you want to {actionType} this request?
          </Typography>
          {selectedApproval && (
            <Box>
              <Typography variant="body2">
                <strong>Customer:</strong> {selectedApproval["Customer Name"]}
              </Typography>
              <Typography variant="body2">
                <strong>Username:</strong> {selectedApproval.Username}
              </Typography>
              <Typography variant="body2">
                <strong>Change Amount:</strong>{" "}
                {selectedApproval["Change Amount"]}
              </Typography>
              <Typography variant="body2">
                <strong>Worker:</strong> {selectedApproval.WorkerName}
              </Typography>
              {selectedApproval.Reason && (
                <Typography variant="body2">
                  <strong>Reason:</strong> {selectedApproval.Reason}
                </Typography>
              )}
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <StyledButton
            onClick={confirmAction}
            disabled={isLoading}
            sx={{
              backgroundColor: actionType === "approve" ? "success.main" : "error.main",
              "&:hover": {
                backgroundColor:
                  actionType === "approve" ? "success.dark" : "error.dark",
              },
            }}
          >
            {isLoading
              ? "Processing..."
              : `Confirm ${actionType === "approve" ? "Approval" : "Denial"}`}
          </StyledButton>
          <StyledButton onClick={handleCloseDialog} disabled={isLoading}>
            Cancel
          </StyledButton>
        </DialogActions>
      </Dialog>

      <Dialog open={reasonDialogText !== null} onClose={() => setReasonDialogText(null)} maxWidth="sm" fullWidth>
        <DialogTitle>Reason</DialogTitle>
        <DialogContent>
          <Typography sx={{ whiteSpace: "pre-wrap", wordBreak: "break-word" }}>
            {reasonDialogText}
          </Typography>
        </DialogContent>
        <DialogActions>
          <StyledButton onClick={() => setReasonDialogText(null)}>Close</StyledButton>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ApprovalsTab;
